// Generated by Claude Team Kit — помічник для перевірки верстки на різних ширинах екрана (Playwright).
// Копія лежить у <e2e>/_helpers/layout-checks.ts. Використання у тесті:
//
//   import { test } from '@playwright/test';
//   import { WIDTHS, eachWidth, checkLayout } from './_helpers/layout-checks';
//
//   test('AC-1 [responsive] сторінка профілю на всіх ширинах', async ({ page }, testInfo) => {
//     await page.goto('/profile');
//     await eachWidth(page, WIDTHS.deep, async (width) => {
//       await checkLayout(page, testInfo, { name: `profile-${width}` });
//     });
//   });
//
// Що перевіряється автоматично (помилка = тест падає):
//   page-horizontal-scroll — у сторінки зʼявився горизонтальний скрол;
//   outside-viewport       — елемент вилазить за край екрана (не всередині контейнера з прокруткою);
//   overflows-parent       — вміст вилазить за межі своєї картки/блока;
//   text-clipped           — текст обрізаний без трьох крапок;
//   content-clipped        — вміст по висоті обрізаний контейнером з overflow:hidden;
//   overlap                — два текстові/інтерактивні елементи накладаються один на одного;
//   covered                — кнопку/поле/посилання перекриває інший елемент (хедер, модалка, z-index);
//   broken-image           — картинка не завантажилась.
// Попередження (у звіт, тест не падає): text-truncated (три крапки), small-target (<24px), small-text (<11px).
import { expect, type Page, type TestInfo } from '@playwright/test';
import fs from 'node:fs';
import path from 'node:path';

/** Набори ширин екрана за глибиною тестування: smoke — 3, deep — 7, exhaustive — 13. */
export const WIDTHS = {
  smoke: [375, 768, 1280],
  deep: [320, 375, 414, 768, 1024, 1280, 1536],
  exhaustive: [320, 360, 375, 390, 414, 480, 600, 768, 834, 1024, 1280, 1440, 1920],
};

/** Одна знахідка перевірки верстки. */
export type LayoutIssue = { kind: string; severity: 'error' | 'warn'; selector: string; detail: string };

/** Підбирає розумну висоту вікна для заданої ширини (телефон, планшет, десктоп). */
export function heightFor(width: number): number {
  if (width <= 480) return 800;
  if (width <= 834) return 1024;
  return 800;
}

/** Виставляє розмір вікна і чекає, поки верстка «заспокоїться» (шрифти, анімації, перерахунок). */
export async function setSize(page: Page, width: number, height = heightFor(width)): Promise<void> {
  await page.setViewportSize({ width, height });
  await page.evaluate(() => document.fonts?.ready);
  await page.waitForTimeout(150);
}

/** Проходить по списку ширин: для кожної виставляє розмір і викликає перевірку `fn`. */
export async function eachWidth(page: Page, widths: number[], fn: (width: number) => Promise<void>): Promise<void> {
  for (const width of widths) {
    await setSize(page, width);
    await fn(width);
  }
}

/** Збирає знахідки верстки на поточній сторінці (код виконується всередині браузера). */
export async function auditLayout(page: Page, opts: { ignore?: string[] } = {}): Promise<LayoutIssue[]> {
  return page.evaluate((ignore) => {
    /** Результат: список знахідок. */
    const issues: { kind: string; severity: 'error' | 'warn'; selector: string; detail: string }[] = [];
    /** Ширина видимої області. */
    const vw = document.documentElement.clientWidth;
    /** Селектори, які треба пропустити (наприклад, декоративні елементи). */
    const skip = (el: Element) => ignore.some((s) => el.matches(s) || el.closest(s));

    /** Короткий опис елемента для звіту: data-testid, id або тег із класами. */
    const sel = (el: Element): string => {
      // Data-testid елемента для зрозумілого опису
      const tid = el.getAttribute('data-testid');
      if (tid) return `[data-testid="${tid}"]`;
      if (el.id) return `#${el.id}`;
      // Перші класи елемента для опису у звіті
      const cls = (el.getAttribute('class') ?? '').trim().split(/\s+/).filter(Boolean).slice(0, 2).join('.');
      return `${el.tagName.toLowerCase()}${cls ? '.' + cls : ''}`;
    };
    /** Додає знахідку, не дублюючи однакові. */
    const add = (kind: string, severity: 'error' | 'warn', el: Element, detail: string) => {
      if (issues.some((i) => i.kind === kind && i.selector === sel(el))) return;
      issues.push({ kind, severity, selector: sel(el), detail });
    };
    /** Чи елемент видимий (не display:none, не прозорий, має розмір). */
    const visible = (el: Element): boolean => {
      // Обчислені стилі елемента
      const cs = getComputedStyle(el);
      if (cs.display === 'none' || cs.visibility === 'hidden' || Number(cs.opacity) === 0) return false;
      // Геометрія елемента на екрані
      const r = el.getBoundingClientRect();
      return r.width > 0 && r.height > 0;
    };
    /** Чи елемент усередині контейнера з навмисною горизонтальною прокруткою. */
    const insideScroller = (el: Element): boolean => {
      for (let p = el.parentElement; p && p !== document.body && p !== document.documentElement; p = p.parentElement) {
        // Значення overflow-x предка
        const ox = getComputedStyle(p).overflowX;
        if (ox === 'auto' || ox === 'scroll' || ox === 'hidden' || ox === 'clip') return true;
      }
      return false;
    };
    /** Чи елемент має власний текст. */
    const hasOwnText = (el: Element): boolean => [...el.childNodes].some((n) => n.nodeType === 3 && (n.textContent ?? '').trim().length > 0);
    /** Чи елемент інтерактивний. */
    const interactive = (el: Element): boolean => el.matches('a[href],button,input:not([type=hidden]),select,textarea,summary,[role=button],[role=link],[role=tab],[tabindex]:not([tabindex="-1"])');

    // 1. Горизонтальний скрол усієї сторінки
    if (document.documentElement.scrollWidth > vw + 1) {
      add('page-horizontal-scroll', 'error', document.documentElement, `scrollWidth ${document.documentElement.scrollWidth} > ширина екрана ${vw}`);
    }

    /** Усі видимі елементи (обмежуємо кількість, щоб не гальмувати). */
    const all = [...document.body.querySelectorAll('*')].filter((e) => !skip(e) && visible(e)).slice(0, 1500);

    for (const el of all) {
      // Геометрія елемента на екрані
      const r = el.getBoundingClientRect();
      // Обчислені стилі елемента
      const cs = getComputedStyle(el);
      // Чи має елемент власний текст
      const own = hasOwnText(el);

      // 2. Виліт за край екрана
      if ((r.right > vw + 1 || r.left < -1) && !insideScroller(el) && cs.position !== 'fixed') {
        add('outside-viewport', 'error', el, `x: ${Math.round(r.left)}…${Math.round(r.right)}, екран ${vw}px`);
      }

      // 3. Вміст вилазить за межі батька (текст «випав» із картки)
      const parent = el.parentElement;
      if (parent && parent !== document.body && parent !== document.documentElement && (own || interactive(el) || el.tagName === 'IMG')) {
        // Обчислені стилі батьківського елемента
        const pcs = getComputedStyle(parent);
        // Геометрія батьківського елемента
        const pr = parent.getBoundingClientRect();
        // Чи батько обрізає вміст
        const clipsParent = pcs.overflowX !== 'visible' || pcs.overflowY !== 'visible';
        if (!clipsParent && pcs.display !== 'contents' && cs.position !== 'absolute' && cs.position !== 'fixed' && pr.width > 0) {
          if (r.right > pr.right + 1.5 || r.left < pr.left - 1.5) add('overflows-parent', 'error', el, `виходить за межі ${sel(parent)} по горизонталі (${Math.round(r.right - pr.right)}px)`);
        }
      }

      // 4. Обрізаний текст / вміст
      if (own || interactive(el)) {
        if (el.scrollWidth > el.clientWidth + 1 && cs.overflowX !== 'visible' && cs.overflowX !== 'auto' && cs.overflowX !== 'scroll') {
          add(cs.textOverflow === 'ellipsis' ? 'text-truncated' : 'text-clipped', cs.textOverflow === 'ellipsis' ? 'warn' : 'error', el, `scrollWidth ${el.scrollWidth} > clientWidth ${el.clientWidth}`);
        }
        if (el.scrollHeight > el.clientHeight + 2 && (cs.overflowY === 'hidden' || cs.overflowY === 'clip') && !/\d/.test(cs.getPropertyValue('-webkit-line-clamp'))) {
          add('content-clipped', 'error', el, `scrollHeight ${el.scrollHeight} > clientHeight ${el.clientHeight}`);
        }
      }

      // 5. Зламані картинки
      if (el instanceof HTMLImageElement && el.complete && el.naturalWidth === 0 && el.currentSrc) add('broken-image', 'error', el, el.currentSrc.slice(0, 80));

      // 6. Попередження: малі цілі дотику і дрібний текст
      if (interactive(el) && vw <= 480 && (r.width < 24 || r.height < 24)) add('small-target', 'warn', el, `${Math.round(r.width)}×${Math.round(r.height)}px`);
      if (own && parseFloat(cs.fontSize) < 11) add('small-text', 'warn', el, `${cs.fontSize}`);
    }

    // 7. Накладання між собою текстових та інтерактивних елементів (листові елементи)
    const leaves = all.filter((e) => (hasOwnText(e) || interactive(e) || e.tagName === 'IMG') && getComputedStyle(e).position !== 'absolute').slice(0, 400);
    for (let i = 0; i < leaves.length; i++) {
      for (let j = i + 1; j < leaves.length; j++) {
        // Перший елемент пари для перевірки перекриття
        const a = leaves[i]; const b = leaves[j];
        if (a.contains(b) || b.contains(a)) continue;
        // Допоміжне значення
        const ra = a.getBoundingClientRect(); const rb = b.getBoundingClientRect();
        // Ширина перетину
        const w = Math.min(ra.right, rb.right) - Math.max(ra.left, rb.left);
        // Висота
        const h = Math.min(ra.bottom, rb.bottom) - Math.max(ra.top, rb.top);
        if (w <= 2 || h <= 2) continue;
        // Площа меншого з двох елементів
        const smaller = Math.min(ra.width * ra.height, rb.width * rb.height);
        if (w * h > smaller * 0.15) add('overlap', 'error', a, `накладається на ${sel(b)} (${Math.round(w)}×${Math.round(h)}px)`);
      }
    }

    // 8. Інтерактивні елементи, які перекриває щось інше (хедер, модалка, z-index)
    for (const el of all.filter(interactive).slice(0, 150)) {
      el.scrollIntoView({ block: 'center', inline: 'center' });
      // Геометрія елемента на екрані
      const r = el.getBoundingClientRect();
      if (r.width === 0 || r.height === 0 || r.bottom < 0 || r.top > innerHeight) continue;
      // Елемент, що фактично лежить у центрі контролу
      const top = document.elementFromPoint(Math.min(Math.max(r.left + r.width / 2, 0), vw - 1), Math.min(Math.max(r.top + r.height / 2, 0), innerHeight - 1));
      if (top && top !== el && !el.contains(top) && !top.contains(el)) add('covered', 'error', el, `у центрі лежить ${sel(top)}`);
    }
    window.scrollTo(0, 0);
    return issues;
  }, opts.ignore ?? []);
}

/** Знаходить корінь воркспейсу (папку з .pipeline/workspace.json), рухаючись угору від файлу тесту. */
function findRoot(from: string): string | null {
  for (let dir = path.dirname(from); ; dir = path.dirname(dir)) {
    if (fs.existsSync(path.join(dir, '.pipeline', 'workspace.json'))) return dir;
    if (path.dirname(dir) === dir) return null;
  }
}

/**
 * Перевіряє верстку поточної сторінки на поточній ширині:
 * знімає скріншот (додається до звіту), пише рядок у .pipeline/<задача>/layout.jsonl
 * (за цим файлом скрипт рахує, скільки ширин реально перевірено) і валить тест, якщо є помилки.
 */
export async function checkLayout(page: Page, testInfo: TestInfo, opts: { name: string; ignore?: string[]; fullPage?: boolean }): Promise<LayoutIssue[]> {
  // Знайдені проблеми розкладки
  const issues = await auditLayout(page, { ignore: opts.ignore });
  // Поточний розмір в’юпорту
  const size = page.viewportSize() ?? { width: 0, height: 0 };
  // Знімок сторінки для звіту
  const shot = await page.screenshot({ fullPage: opts.fullPage ?? true });
  await testInfo.attach(`layout-${opts.name}.png`, { body: shot, contentType: 'image/png' });

  // Ідентифікатор задачі з імені файлу
  const taskId = path.basename(testInfo.file).replace(/\.(spec|test)\.(ts|js)$/, '');
  // Корінь репозиторію
  const root = findRoot(testInfo.file);
  if (root) {
    // Тека для артефактів задачі
    const dir = path.join(root, '.pipeline', taskId);
    fs.mkdirSync(dir, { recursive: true });
    // Проблеми рівня error
    const errors = issues.filter((i) => i.severity === 'error');
    fs.appendFileSync(path.join(dir, 'layout.jsonl'), JSON.stringify({
      name: opts.name, width: size.width, height: size.height, url: page.url(), test: testInfo.title,
      errors: errors.length, warnings: issues.length - errors.length, issues: issues.slice(0, 20), at: new Date().toISOString(),
    }) + '\n');
  }
  // Проблеми рівня error
  const errs = issues.filter((i) => i.severity === 'error');
  expect(errs, `Проблеми верстки (${opts.name}, ${size.width}px):\n${errs.map((i) => `  • ${i.kind} ${i.selector}: ${i.detail}`).join('\n')}`).toEqual([]);
  return issues;
}
